PRAGMA foreign_keys = ON;
CREATE TABLE users (id TEXT PRIMARY KEY,email TEXT NOT NULL UNIQUE,email_verified_at TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE accounts (id TEXT PRIMARY KEY,name TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE account_users (account_id TEXT NOT NULL REFERENCES accounts(id),user_id TEXT NOT NULL REFERENCES users(id),role TEXT NOT NULL CHECK(role IN ('owner','admin','member')),PRIMARY KEY(account_id,user_id));
CREATE TABLE plans (id TEXT PRIMARY KEY,name TEXT NOT NULL,stripe_price_id TEXT NOT NULL UNIQUE,monthly_price INTEGER NOT NULL,max_queries INTEGER NOT NULL,allowed_providers TEXT NOT NULL,run_frequency TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE subscriptions (id TEXT PRIMARY KEY,account_id TEXT NOT NULL REFERENCES accounts(id),plan_id TEXT NOT NULL REFERENCES plans(id),stripe_customer_id TEXT NOT NULL,stripe_subscription_id TEXT UNIQUE,status TEXT NOT NULL,period_start TEXT,period_end TEXT,updated_at TEXT NOT NULL);
CREATE TABLE projects (id TEXT PRIMARY KEY,account_id TEXT NOT NULL REFERENCES accounts(id),name TEXT NOT NULL,primary_domain TEXT NOT NULL,providers TEXT NOT NULL,frequency TEXT NOT NULL DEFAULT 'monthly',created_at TEXT NOT NULL,last_run_at TEXT,next_run_at TEXT);
CREATE INDEX projects_account_idx ON projects(account_id);
CREATE TABLE project_domains (id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,domain TEXT NOT NULL,type TEXT NOT NULL,UNIQUE(project_id,domain));
CREATE TABLE queries (id TEXT PRIMARY KEY,account_id TEXT NOT NULL REFERENCES accounts(id),text TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE project_queries (project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,query_id TEXT NOT NULL REFERENCES queries(id),active INTEGER NOT NULL DEFAULT 1,PRIMARY KEY(project_id,query_id));
CREATE TABLE providers (id TEXT PRIMARY KEY,name TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1,configuration TEXT);
CREATE TABLE runs (id TEXT PRIMARY KEY,account_id TEXT NOT NULL REFERENCES accounts(id),project_id TEXT NOT NULL REFERENCES projects(id),status TEXT NOT NULL,idempotency_key TEXT NOT NULL UNIQUE,request_id TEXT NOT NULL,created_at TEXT NOT NULL,completed_at TEXT);
CREATE TABLE run_queries (id TEXT PRIMARY KEY,run_id TEXT NOT NULL REFERENCES runs(id),query_id TEXT NOT NULL REFERENCES queries(id),provider_id TEXT NOT NULL REFERENCES providers(id),status TEXT NOT NULL,attempts INTEGER NOT NULL DEFAULT 0,error_code TEXT,error_message TEXT,UNIQUE(run_id,query_id,provider_id));
CREATE TABLE provider_results (id TEXT PRIMARY KEY,run_query_id TEXT NOT NULL UNIQUE REFERENCES run_queries(id),answer_present INTEGER NOT NULL,answer_text TEXT,cited INTEGER NOT NULL,mentioned INTEGER NOT NULL,citation_position INTEGER,search_id TEXT,raw_object_key TEXT,normalized_json TEXT NOT NULL,executed_at TEXT NOT NULL);
CREATE TABLE citations (id TEXT PRIMARY KEY,provider_result_id TEXT NOT NULL REFERENCES provider_results(id),url TEXT NOT NULL,domain TEXT NOT NULL,title TEXT,position INTEGER NOT NULL);
CREATE TABLE usage_events (id TEXT PRIMARY KEY,account_id TEXT NOT NULL,subscription_id TEXT NOT NULL,run_id TEXT NOT NULL,query_id TEXT NOT NULL,provider TEXT NOT NULL,units INTEGER NOT NULL,period_start TEXT NOT NULL,period_end TEXT NOT NULL,created_at TEXT NOT NULL,UNIQUE(run_id,query_id,provider));
CREATE TABLE exports (id TEXT PRIMARY KEY,account_id TEXT NOT NULL,run_id TEXT NOT NULL,format TEXT NOT NULL,status TEXT NOT NULL,object_key TEXT,created_at TEXT NOT NULL,UNIQUE(run_id,format));
CREATE TABLE scheduled_jobs (id TEXT PRIMARY KEY,account_id TEXT NOT NULL,project_id TEXT NOT NULL,job_type TEXT NOT NULL,status TEXT NOT NULL,attempts INTEGER NOT NULL DEFAULT 0,next_attempt_at TEXT,error_code TEXT,request_id TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE webhook_events (id TEXT PRIMARY KEY,provider TEXT NOT NULL,event_type TEXT NOT NULL,status TEXT NOT NULL,payload_hash TEXT NOT NULL,received_at TEXT NOT NULL,processed_at TEXT,error_code TEXT);
CREATE TABLE audit_events (id TEXT PRIMARY KEY,account_id TEXT,user_id TEXT,type TEXT NOT NULL,request_id TEXT NOT NULL,metadata TEXT,created_at TEXT NOT NULL);
